update public.global_settings set landing_content = jsonb_set(coalesce(landing_content, '{}'::jsonb), '{features,items}', '[{"icon":"Boxes","title":"হাজারো প্রোডাক্ট, এক ক্লিকে লিস্ট","desc":"ভেরিফাইড ক্যাটালগ, HD ছবি, SEO কন্টেন্ট — স্টক কিনতে হবে না।"},{"icon":"Wallet","title":"নিজের প্রফিট নিজে ঠিক করুন","desc":"কস্ট দেখেই মার্জিন বসান, পুরো প্রফিট আপনার।"},{"icon":"Truck","title":"কুরিয়ার বুকিং আমরা করি","desc":"Steadfast, Pathao, CarryBee — প্যাকেজিং থেকে ট্র্যাকিং পর্যন্ত।"}]'::jsonb) where id = 1;